def write_once(path, text):
    if path.exists():
        return False
    path.write_text(text, encoding="utf-8")
    return True

def write_if_changed(path, text):
    if path.exists() and path.read_text(encoding="utf-8") == text:
        return False
    path.write_text(text, encoding="utf-8")
    return True
